/* ------------------------------------------------------------------ */
/*  ĐỌC TIẾNG HÀN DIỄN CẢM (Web Speech API)                            */
/*  - Nhân vật A: giọng cao, nhanh vừa | Nhân vật B: giọng trầm hơn    */
/*  - Câu hỏi (?) tự động lên giọng; câu cảm (!) đọc nhấn hơn          */
/*  - "Nghe cả đoạn": đọc lần lượt từng lượt thoại, ngắt nghỉ tự nhiên */
/* ------------------------------------------------------------------ */
const cleanKo = (t) => t.replace(/\*\*/g, "").replace(/[\[\]]/g, "");

const pickKoVoice = () => {
  const vs = window.speechSynthesis?.getVoices?.() || [];
  return (
    vs.find((v) => v.lang === "ko-KR" && /Yuna|Google|Heami|SunHi/i.test(v.name)) ||
    vs.find((v) => v.lang?.startsWith("ko")) ||
    null
  );
};

const makeUtter = (text, { spk = "A" } = {}) => {
  const u = new SpeechSynthesisUtterance(cleanKo(text));
  u.lang = "ko-KR";
  const voice = pickKoVoice();
  if (voice) u.voice = voice;

  const isQuestion = /\?\s*$/.test(text);
  const isExclaim = /!\s*$/.test(text);

  // tính cách giọng theo nhân vật
  if (spk === "B") { u.pitch = 0.85; u.rate = 0.86; }
  else { u.pitch = 1.12; u.rate = 0.9; }

  // ngữ điệu: câu hỏi lên giọng, câu cảm thán nhấn mạnh
  if (isQuestion) u.pitch += 0.15;
  if (isExclaim) { u.pitch += 0.08; u.rate += 0.06; u.volume = 1; }

  return u;
};

/* Đọc một câu (dùng cho nút loa từng dòng và từ vựng) */
const speakKo = (text, opts = {}) => {
  try {
    window.speechSynthesis.cancel();
    window.speechSynthesis.speak(makeUtter(text, opts));
  } catch (e) { /* trình duyệt không hỗ trợ TTS */ }
};

/* Đọc cả đoạn hội thoại: từng lượt thoại nối tiếp, đổi giọng A/B */
const speakDialogue = (lines) => {
  try {
    const synth = window.speechSynthesis;
    synth.cancel();
    lines.forEach((d) => synth.speak(makeUtter(d.ko, { spk: d.spk })));
  } catch (e) { /* trình duyệt không hỗ trợ TTS */ }
};

/* Tô tím từ mục tiêu trong câu ví dụ (phần nằm giữa ** **) */
const renderKo = (ko) =>
  ko.split("**").map((part, i) =>
    i % 2 === 1 ? <span key={i} className="hl">{part}</span> : <span key={i}>{part}</span>
  );

