function getGreeting() {
  const h = new Date().getHours();
  if (h < 11) return "Chào buổi sáng";
  if (h < 14) return "Chào buổi trưa";
  if (h < 18) return "Chào buổi chiều";
  return "Chào buổi tối";
}

function Header({ profile, onOpenNotif }) {
  const [stats, setStats] = useState(null);
  const [hasNotif, setHasNotif] = useState(false);

  useEffect(() => {
    let alive = true;
    if (!profile) return;
    computeAndSyncUserStats(profile).then((s) => { if (alive) setStats(s); });
    hasNewCommunityActivity().then((v) => { if (alive) setHasNotif(v); });
    return () => { alive = false; };
  }, [profile]);

  const xp = stats?.xp ?? 0;
  const xpMax = Math.max(200, Math.ceil((xp + 1) / 200) * 200); // mốc cấp kế tiếp, tăng dần theo XP thật
  const level = Math.max(1, Math.floor(xp / 200) + 1);
  const xpPct = xpMax ? ((xp % 200) / 200) * 100 : 0;
  const streak = stats?.streak ?? 0;
  const name = profile?.displayName || "bạn";

  return (
    <section className="header">
      <button className="avatar-btn" onClick={onOpenNotif} aria-label="Thông báo">
        <Avatar />
        {hasNotif && <span className="notif-dot" title="Có thông báo mới" />}
      </button>
      <div className="hello">
        <h1>{getGreeting()}, <span>{name}!</span> 👋</h1>
        <p>Hôm nay học một chút,<br />ngày mai tiến bộ hơn nhé! 💜</p>
        <div className="chips">
          <div className="chip">
            <div className="chip-ico" style={{ background: "#FDEDE3" }}><Flame size={20} color="#F0642E" fill="#F79A5E" /></div>
            <div><b>{streak}</b><small>Ngày streak</small></div>
          </div>
          <button className="chip chip-btn" onClick={onOpenNotif}>
            <div className="chip-ico" style={{ background: "#EBF4FD", position: "relative" }}>
              <Bell size={20} color="#4A90E2" />
              {hasNotif && <span className="notif-dot notif-dot-sm" />}
            </div>
            <div><b>{hasNotif ? "Mới" : "—"}</b><small>Thông báo</small></div>
          </button>
        </div>
      </div>
      <div className="level-card">
        <div className="level-top">
          <div className="hex">
            <Hexagon size={44} color="#7C6FE4" fill="#8B7BE8" strokeWidth={1.4} />
            <Star size={17} color="#fff" fill="#fff" className="hex-star" />
          </div>
          <div className="level-info">
            <b>Lv. {level}</b>
            <span className="xp-num">{xp.toLocaleString("vi-VN")} XP</span>
          </div>
        </div>
        <Bar pct={xpPct} color="#8B7BE8" h={9} />
        <div className="level-sub">Học viên chăm chỉ</div>
      </div>
    </section>
  );
}

/* Thuật toán tính % tiến độ học THẬT trên trang chủ — đọc từ đúng dữ liệu   */
/* đã lưu (Leitner box từ vựng, điểm Shadowing, kết quả Nghe chép, lịch sử   */
/* Ôn tập), không còn số cố định. Tính trên Bài 1 (bài duy nhất có dữ liệu). */
async function computeHomeProgress() {
  const lesson = LESSONS_2_1[0];
  const out = [
    { key: "tuvung", label: "Từ vựng & Ngữ pháp", pct: 0, detail: `0 / ${VOCAB_SAMPLE.length} từ`, color: "#4A90E2", bg: "#EEF4FD", icon: "book" },
    { key: "nghe", label: "Nghe chép chính tả", pct: 0, detail: `0 / ${SHADOW_LINES.length} câu`, color: "#3FA95C", bg: "#EBF7EE", icon: "head" },
    { key: "shadowing", label: "Shadowing", pct: 0, detail: `0 / ${SHADOW_LINES.length} câu`, color: "#7C6FE4", bg: "#F0EEFC", icon: "mic" },
    { key: "ungdung", label: "Ôn tập", pct: 0, detail: "Chưa ôn tập", color: "#F0912E", bg: "#FDF3E7", icon: "chat" },
  ];
  try {
    const v = await window.storage.get(vocabProgressKey(lesson));
    if (v?.value) {
      const n = Object.keys(JSON.parse(v.value)).length;
      out[0].pct = Math.round((n / VOCAB_SAMPLE.length) * 100);
      out[0].detail = `${n} / ${VOCAB_SAMPLE.length} từ`;
    }
  } catch (e) {}
  try {
    const d = await window.storage.get(dictationProgressKey(lesson));
    if (d?.value) {
      const parsed = correctDictationResults(JSON.parse(d.value));
      const n = Object.keys(parsed).length;
      out[1].pct = Math.round((n / SHADOW_LINES.length) * 100);
      out[1].detail = `${n} / ${SHADOW_LINES.length} câu`;
    }
  } catch (e) {}
  try {
    const s = await window.storage.get(shadowProgressKey(lesson));
    if (s?.value) {
      const n = Object.keys(JSON.parse(s.value)).length;
      out[2].pct = Math.round((n / SHADOW_LINES.length) * 100);
      out[2].detail = `${n} / ${SHADOW_LINES.length} câu`;
    }
  } catch (e) {}
  try {
    const r = await window.storage.get(reviewHistoryKey(lesson));
    if (r?.value) {
      const hist = JSON.parse(r.value);
      const totalReviewable = VOCAB_SAMPLE.length + GRAMMAR_SAMPLE.reduce((s, g) => s + g.formula.length, 0) + SHADOW_LINES.length + (SHADOW_LINES.length - 1);
      const mastered = Object.values(hist).filter((h) => h.correct > 0 && h.correct >= h.wrong).length;
      out[3].pct = Math.round((mastered / totalReviewable) * 100);
      out[3].detail = `${mastered} / ${totalReviewable} mục đã vững`;
    }
  } catch (e) {}
  return out;
}

function RadarChart({ axes, size = 200 }) {
  const cx = size / 2, cy = size / 2, r = size / 2 - 38;
  const n = axes.length;
  const angleFor = (i) => (-90 + i * (360 / n)) * (Math.PI / 180);
  const pointAt = (i, scale) => {
    const a = angleFor(i);
    return [cx + r * scale * Math.cos(a), cy + r * scale * Math.sin(a)];
  };
  const dataPoints = axes.map((ax, i) => pointAt(i, Math.max(0.04, ax.pct / 100)));
  const dataPath = dataPoints.map((p) => p.join(",")).join(" ");

  return (
    <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size}>
      {[0.25, 0.5, 0.75, 1].map((lv, idx) => (
        <polygon key={idx} points={axes.map((_, i) => pointAt(i, lv).join(",")).join(" ")} fill="none" stroke="#E7E3F6" strokeWidth="1" />
      ))}
      {axes.map((_, i) => {
        const [x, y] = pointAt(i, 1);
        return <line key={i} x1={cx} y1={cy} x2={x} y2={y} stroke="#E7E3F6" strokeWidth="1" />;
      })}
      <polygon points={dataPath} fill="rgba(124,111,228,.35)" stroke="#7C6FE4" strokeWidth="2" strokeLinejoin="round" />
      {dataPoints.map(([x, y], i) => <circle key={i} cx={x} cy={y} r="3.5" fill="#7C6FE4" />)}
      {axes.map((ax, i) => {
        const [lx, ly] = pointAt(i, 1.26);
        return (
          <text key={i} x={lx} y={ly} textAnchor="middle" dominantBaseline="middle" fontSize="10.5" fontWeight="800" fill="#4B4470">
            {ax.label}
          </text>
        );
      })}
    </svg>
  );
}

