function LeaderboardView({ profile, onBack, hideHeader }) {
  const [lb, setLb] = useState(null);
  useEffect(() => {
    let alive = true;
    computeLeaderboard(profile).then((l) => { if (alive) setLb(l); });
    return () => { alive = false; };
  }, [profile]);

  return (
    <section className="cg-page wide-page leaderboard-page">
      {!hideHeader && (
        <div className="fc2-topbar">
          <div className="fc2-top-left">
            <button className="fc2-back" onClick={onBack} aria-label="Về trang chủ"><ChevronLeft size={20} /></button>
            <span className="fc2-title"><Trophy size={18} color="#F0912E" /> Bảng xếp hạng</span>
          </div>
        </div>
      )}
      <p className="cg-sub" style={{ marginTop: 0 }}>
        Xếp hạng theo điểm kinh nghiệm (XP) tích luỹ từ tiến độ học thật (từ vựng, nghe chép, shadowing, ôn tập) — dùng chung cho mọi người học.
      </p>
      {!lb ? (
        <div className="cg-empty">Đang tải...</div>
      ) : lb.rows.length === 0 ? (
        <div className="cg-empty">Chưa có ai trên bảng xếp hạng — hãy là người đầu tiên học và ghi điểm!</div>
      ) : (
        <div className="lb-list">
          {lb.rows.map((u, i) => {
            const isMe = (u.displayName || "").toLowerCase() === (profile.displayName || "").toLowerCase();
            return (
              <div key={u.displayName + i} className={`lb-row ${isMe ? "me" : ""}`}>
                <span className="lb-rank">{i < 3 ? ["🥇", "🥈", "🥉"][i] : i + 1}</span>
                <span className="lb-name">{u.displayName}{isMe && " (bạn)"}</span>
                <span className="lb-streak"><Flame size={13} color="#F0642E" fill="#F79A5E" /> {u.streak}</span>
                <span className="lb-xp">{u.xp.toLocaleString("vi-VN")} XP</span>
              </div>
            );
          })}
        </div>
      )}
    </section>
  );
}

