const normalizeKo = (s) =>
  (s || "")
    .replace(/\*\*/g, "")
    .replace(/[.,?!~…"“”'‘’]/g, "")
    .trim()
    .split(/\s+/)
    .filter(Boolean);

function compareSpeech(target, said) {
  const targetWords = normalizeKo(target);
  const saidPool = normalizeKo(said);
  const wordResults = targetWords.map((w) => {
    const i = saidPool.indexOf(w);
    if (i !== -1) { saidPool.splice(i, 1); return { word: w, ok: true }; }
    return { word: w, ok: false };
  });
  const okCount = wordResults.filter((w) => w.ok).length;
  const score = targetWords.length ? Math.round((okCount / targetWords.length) * 100) : 0;
  return { wordResults, score, extraWords: saidPool };
}

const feedbackFor = (score, hasSpeech) => {
  if (!hasSpeech) return { tone: "bad", msg: "Chưa nhận diện được giọng nói. Nói to, rõ và gần micro hơn rồi thử lại." };
  if (score === 100) return { tone: "great", msg: "Xuất sắc! Bạn đã nói đúng toàn bộ câu." };
  if (score >= 70) return { tone: "good", msg: "Khá tốt! Chú ý đọc lại rõ hơn (các) từ được tô đỏ bên dưới." };
  if (score >= 40) return { tone: "mid", msg: "Cần luyện thêm — nghe lại mẫu rồi thử nói chậm, rõ từng từ." };
  return { tone: "bad", msg: "Còn khá khác so với câu gốc — nghe lại mẫu vài lần rồi thử lại nhé." };
};

const toneForScore = (score) => (score >= 80 ? "good" : score >= 60 ? "mid" : "bad");

const AI_GRADER_URL = (import.meta.env.VITE_AI_GRADER_URL || "https://ai-review-paper.vonhacphuoc.workers.dev/").replace(/\/?$/, "/");

function parseAIJson(value) {
  const clean = String(value || "").replace(/```(?:json)?/gi, "").replace(/```/g, "").trim();
  try { return JSON.parse(clean); } catch (error) {
    const start = clean.indexOf("{");
    const end = clean.lastIndexOf("}");
    if (start >= 0 && end > start) return JSON.parse(clean.slice(start, end + 1));
    throw error;
  }
}

