function ShadowingView({ lesson, onBack, onFinish }) {
  const [idx, setIdx] = useState(0);
  const [autoPlay, setAutoPlay] = useState(false);
  const [status, setStatus] = useState("idle"); // idle | recording | grading | done | error | unsupported
  const [results, setResults] = useState({});
  const [history, setHistory] = useState([]);
  const [errMsg, setErrMsg] = useState("");
  const [helpPanel, setHelpPanel] = useState(null); // null | "break" | "pron" | "tips"
  const [audioTime, setAudioTime] = useState(0);
  const [audioDuration, setAudioDuration] = useState(0);
  const [recordingElapsed, setRecordingElapsed] = useState(0);
  const [recordedUrls, setRecordedUrls] = useState({}); // { [idx]: blob url } — bản ghi âm THẬT của người dùng để nghe lại
  const [showCompletion, setShowCompletion] = useState(false);
  const [finalAssessment, setFinalAssessment] = useState(null);
  const [assessingFinal, setAssessingFinal] = useState(false);
  const [isRecheck, setIsRecheck] = useState(false);
  const [micBlocked, setMicBlocked] = useState(false); // getUserMedia bị chặn (thường do khung xem trước) — chỉ ảnh hưởng phần ghi âm để nghe lại, không chặn chấm điểm AI
  const recognitionRef = useRef(null);
  const audioRef = useRef(null);
  const autoPlayTimer = useRef(null);
  const mediaRecorderRef = useRef(null);
  const recordedChunksRef = useRef([]);
  const mediaStreamRef = useRef(null);
  const myRecAudioRef = useRef(null);
  const recordingStartedAtRef = useRef(0);
  const recordingIntervalRef = useRef(null);
  const recordingTimeoutRef = useRef(null);
  const autoAdvanceRef = useRef(null);
  const recognizedTextRef = useRef("");
  const recordingFinishingRef = useRef(false);

  const line = SHADOW_LINES[idx];
  const total = SHADOW_LINES.length;
  const result = results[idx];
  const shadowQuestionDone = result?.score >= 80;
  // Cho người học thêm 3 giây so với thời lượng câu mẫu để lấy hơi và kết câu.
  // Audio chưa tải metadata thì ước lượng theo độ dài câu, tránh giới hạn bằng 0.
  const estimatedSampleDuration = Math.max(2, line.ko.length / 6);
  const recordingLimit = Math.max(4, Math.ceil((audioDuration || estimatedSampleDuration) + 3));

  const speechSupported =
    typeof window !== "undefined" && !!(window.SpeechRecognition || window.webkitSpeechRecognition);

  useEffect(() => {
    let active = true;
    window.storage.get(shadowProgressKey(lesson)).then((saved) => {
      if (!active || !saved?.value) return;
      try {
        const restored = Object.fromEntries(
          Object.entries(JSON.parse(saved.value)).filter(([, item]) => item?.score >= 80),
        );
        setResults(restored);
        setHistory(Object.entries(restored).map(([key, item]) => ({
          no: SHADOW_LINES[Number(key)]?.no || Number(key) + 1,
          ko: SHADOW_LINES[Number(key)]?.ko || "",
          score: item.score,
        })).reverse().slice(0, 12));
        if (SHADOW_LINES.every((_, questionIndex) => restored[questionIndex]?.score >= 80)) finishAndAssess(restored);
      } catch (error) { /* dữ liệu cũ không hợp lệ thì bắt đầu phiên mới */ }
    });
    return () => { active = false; };
  }, [lesson]);

  useEffect(() => {
    setErrMsg("");
    setStatus("idle");
    setHelpPanel(null);
    setAudioTime(0);
    setRecordingElapsed(0);
    clearInterval(recordingIntervalRef.current);
    clearTimeout(recordingTimeoutRef.current);
    clearTimeout(autoAdvanceRef.current);
    recordingFinishingRef.current = false;
    recognizedTextRef.current = "";
  }, [idx]);

  useEffect(() => () => {
    clearInterval(recordingIntervalRef.current);
    clearTimeout(recordingTimeoutRef.current);
    clearTimeout(autoAdvanceRef.current);
    try { recognitionRef.current?.abort(); } catch (e) {}
  }, []);

  // Tự động phát khi bật "Tự động phát" và mỗi khi chuyển câu
  useEffect(() => {
    if (!autoPlay) return;
    clearTimeout(autoPlayTimer.current);
    autoPlayTimer.current = setTimeout(() => {
      const el = audioRef.current;
      if (el) { el.currentTime = 0; el.play().catch(() => {}); }
    }, 350);
    return () => clearTimeout(autoPlayTimer.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idx, autoPlay]);

  const playNative = () => {
    const el = audioRef.current;
    if (!el) return;
    el.currentTime = 0;
    el.play().catch(() => {});
  };

  const playMyRecording = () => {
    const url = recordedUrls[idx];
    if (!url) return;
    if (!myRecAudioRef.current) myRecAudioRef.current = new Audio();
    myRecAudioRef.current.src = url;
    myRecAudioRef.current.currentTime = 0;
    myRecAudioRef.current.play().catch(() => {});
  };

  // Ghi âm THẬT giọng người dùng (khác với nhận diện giọng nói để AI chấm
  // điểm bên dưới) — để họ có thể tự nghe lại và so sánh với giọng mẫu.
  const startMediaRecording = async () => {
    if (!window.isSecureContext) {
      setMicBlocked(true);
      setErrMsg("Micro chỉ hoạt động trên HTTPS hoặc localhost. Hãy mở bản deploy HTTPS của ứng dụng.");
      setStatus("error");
      return false;
    }
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") {
      setMicBlocked(true);
      setErrMsg("Trình duyệt này chưa hỗ trợ ghi âm. Hãy dùng Chrome hoặc Edge phiên bản mới nhất.");
      setStatus("unsupported");
      return false;
    }
    try {
      // Xin quyền và khởi động recorder xong trước khi bật SpeechRecognition.
      // Nếu không chờ bước này, recognition có thể kết thúc trong lúc hộp cấp
      // quyền micro vẫn đang mở, khiến recorder khởi động muộn và không lưu file.
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
          channelCount: 1,
        },
      });
      mediaStreamRef.current = stream;
      recordedChunksRef.current = [];
      const preferredTypes = [
        "audio/webm;codecs=opus",
        "audio/webm",
        "audio/mp4",
        "audio/ogg;codecs=opus",
      ];
      const mimeType = preferredTypes.find((type) => MediaRecorder.isTypeSupported?.(type));
      const mr = mimeType ? new MediaRecorder(stream, { mimeType }) : new MediaRecorder(stream);
      mr.ondataavailable = (e) => { if (e.data && e.data.size > 0) recordedChunksRef.current.push(e.data); };
      mr.onstop = () => {
        const blob = new Blob(recordedChunksRef.current, { type: mr.mimeType || "audio/webm" });
        if (blob.size > 0) {
          const url = URL.createObjectURL(blob);
          setRecordedUrls((prev) => {
            if (prev[idx]) URL.revokeObjectURL(prev[idx]);
            return { ...prev, [idx]: url };
          });
        }
        stream.getTracks().forEach((t) => t.stop());
        if (mediaStreamRef.current === stream) mediaStreamRef.current = null;
        if (mediaRecorderRef.current === mr) mediaRecorderRef.current = null;
      };
      mr.onerror = () => {
        setErrMsg("Không thể lưu bản ghi âm. Hãy kiểm tra micro rồi thử lại.");
        setStatus("error");
        stream.getTracks().forEach((track) => track.stop());
      };
      mediaRecorderRef.current = mr;
      mr.start(250);
      setMicBlocked(false);
      return true;
    } catch (e) {
      setMicBlocked(true);
      mediaStreamRef.current?.getTracks().forEach((track) => track.stop());
      mediaStreamRef.current = null;
      const permissionDenied = e?.name === "NotAllowedError" || e?.name === "SecurityError";
      const noDevice = e?.name === "NotFoundError" || e?.name === "DevicesNotFoundError";
      setErrMsg(permissionDenied
        ? "Ứng dụng chưa được cấp quyền micro. Hãy cho phép Microphone trong cài đặt trang rồi tải lại trang."
        : noDevice
          ? "Không tìm thấy micro trên thiết bị. Hãy kết nối micro rồi thử lại."
          : `Không thể mở micro${e?.message ? `: ${e.message}` : ". Hãy thử lại."}`);
      setStatus("error");
      return false;
    }
  };
  const stopMediaRecording = () => {
    const recorder = mediaRecorderRef.current;
    try {
      if (recorder?.state === "recording" || recorder?.state === "paused") recorder.stop();
    } catch (e) {
      mediaStreamRef.current?.getTracks().forEach((track) => track.stop());
      mediaStreamRef.current = null;
      mediaRecorderRef.current = null;
    }
  };

  const releaseRecordedAudio = () => {
    setRecordedUrls((current) => {
      Object.values(current).forEach((url) => { try { URL.revokeObjectURL(url); } catch (error) {} });
      return {};
    });
    recordedChunksRef.current = [];
    try { myRecAudioRef.current?.pause(); } catch (error) {}
    if (myRecAudioRef.current) myRecAudioRef.current.src = "";
  };

  const finishAndAssess = async (completedResults) => {
    setShowCompletion(true);
    setAssessingFinal(true);
    setFinalAssessment(null);
    try {
      const assessment = await assessAbility(SHADOW_LINES.map((_, questionIndex) => ({
        rhythmScore: completedResults[questionIndex]?.score || 0,
        accuracyScore: completedResults[questionIndex]?.score || 0,
      })));
      setFinalAssessment(assessment);
    } catch (error) {
      const average = Math.round(Object.values(completedResults).reduce((sum, item) => sum + (item.score || 0), 0) / total);
      setFinalAssessment({
        level: average >= 90 ? "Khá tốt" : "Đạt yêu cầu",
        summary: `Bạn đã hoàn thành toàn bộ ${total} câu với điểm trung bình ${average}%.`,
        focus: "Hãy nghe lại giọng mẫu định kỳ để giữ nhịp và phát âm ổn định.",
      });
    } finally {
      setAssessingFinal(false);
      releaseRecordedAudio();
    }
  };

  useEffect(() => () => {
    stopMediaRecording();
    Object.values(recordedUrls).forEach((u) => { try { URL.revokeObjectURL(u); } catch (e) {} });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const submitForGrading = async (said) => {
    setStatus("grading");
    setErrMsg("");
    let graded;
    try {
      graded = await gradeWithAI(line.ko, said, line.realPron, {
        elapsed: recordingElapsed,
        limit: recordingLimit,
      });
    } catch (e) {
      graded = gradeLocally(line.ko, said);
      graded.warning = "Dịch vụ AI đang bận nên kết quả này được chấm dự phòng trên thiết bị.";
    }
    const gradedResult = { transcript: said, ...graded, gradedAt: new Date().toISOString() };
    const nextResults = { ...results, [idx]: gradedResult };
    if (graded.score >= 80 && !(results[idx]?.score >= 80)) playCorrectSound();
    else if (graded.score < 80) playIncorrectSound();
    setResults((current) => {
      const next = { ...current, [idx]: gradedResult };
      if (graded.score >= 80) {
        const passed = Object.fromEntries(Object.entries(next).filter(([, item]) => item.score >= 80));
        if (!isRecheck || Object.keys(passed).length === total) {
          window.storage.set(shadowProgressKey(lesson), JSON.stringify(passed)).catch(() => {});
        }
      }
      return next;
    });
    setHistory((h) => [{ no: line.no, ko: line.ko, score: graded.score }, ...h].slice(0, 12));
    setStatus("done");
    if (graded.score >= 80) {
      clearTimeout(autoAdvanceRef.current);
      autoAdvanceRef.current = window.setTimeout(() => {
        if (idx < total - 1) {
          setIdx(idx + 1);
        } else if (SHADOW_LINES.every((_, questionIndex) => nextResults[questionIndex]?.score >= 80)) {
          finishAndAssess(nextResults);
        }
      }, 900);
    }
  };

  const finishRecording = (reason = "manual") => {
    if (recordingFinishingRef.current) return;
    recordingFinishingRef.current = true;
    clearInterval(recordingIntervalRef.current);
    clearTimeout(recordingTimeoutRef.current);
    if (reason === "timeout") setRecordingElapsed(recordingLimit);
    stopMediaRecording();
    try { recognitionRef.current?.stop(); } catch (e) {}
    setStatus("grading");

    // Cho SpeechRecognition một nhịp ngắn để trả nốt phần transcript cuối.
    window.setTimeout(() => {
      const said = recognizedTextRef.current.trim();
      if (!said) {
        setErrMsg(reason === "timeout"
          ? "Đã hết thời gian nhưng chưa nhận được giọng nói. Hãy thử lại và nói gần micro hơn nhé."
          : "Chưa nhận được giọng nói. Hãy thử lại và nói gần micro hơn nhé.");
        setStatus("error");
        return;
      }
      submitForGrading(said);
    }, 220);
  };

  const startRecording = () => {
    if (!speechSupported) { setStatus("unsupported"); return false; }
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    const rec = new SR();
    rec.lang = "ko-KR";
    rec.interimResults = true;
    rec.maxAlternatives = 1;
    rec.continuous = true;

    setErrMsg("");
    setRecordingElapsed(0);
    recognizedTextRef.current = "";
    recordingFinishingRef.current = false;
    setStatus("recording");

    rec.onresult = (e) => {
      let said = "";
      for (let i = 0; i < e.results.length; i += 1) {
        said += `${e.results[i]?.[0]?.transcript || ""} `;
      }
      recognizedTextRef.current = said.trim();
    };
    rec.onerror = (e) => {
      if (recordingFinishingRef.current || e.error === "aborted") return;
      recordingFinishingRef.current = true;
      clearInterval(recordingIntervalRef.current);
      clearTimeout(recordingTimeoutRef.current);
      stopMediaRecording();
      const map = {
        "not-allowed": "Trình duyệt/khung xem trước này chưa cấp quyền micro cho ứng dụng — không phải do bạn thao tác sai. Thử mở app ở môi trường triển khai thật (ngoài khung xem trước) để dùng mic.",
        "no-speech": "Chưa nghe thấy giọng nói, thử nói to hơn nhé.",
        "audio-capture": "Không tìm thấy micro trên thiết bị này.",
        "network": "Khung xem trước này có thể đang chặn kết nối đến máy chủ nhận diện giọng nói — không phải lỗi do bạn.",
      };
      setErrMsg(map[e.error] || "Có lỗi khi nhận diện giọng nói, thử lại nhé.");
      setStatus("error");
    };
    rec.onend = () => {
      // Một số trình duyệt tự kết thúc phiên nhận diện khi người dùng ngừng nói.
      // Khi đó vẫn hoàn tất và chấm phần đã ghi thay vì làm mất bản ghi.
      if (!recordingFinishingRef.current) finishRecording("browser");
    };

    recognitionRef.current = rec;
    try {
      rec.start();
      recordingStartedAtRef.current = Date.now();
      recordingIntervalRef.current = window.setInterval(() => {
        const elapsed = Math.min(recordingLimit, (Date.now() - recordingStartedAtRef.current) / 1000);
        setRecordingElapsed(elapsed);
      }, 100);
      recordingTimeoutRef.current = window.setTimeout(() => finishRecording("timeout"), recordingLimit * 1000);
      return true;
    } catch (err) {
      setErrMsg("Không thể khởi động micro.");
      setStatus("error");
      return false;
    }
  };

  /* Nút mic dùng chung cho cả bắt đầu, dừng+chấm điểm, VÀ ghi âm lại —
     bấm khi đang ghi thì dừng (tự động chấm điểm), bấm khi đã có kết quả
     thì xoá kết quả cũ và ghi âm lại từ đầu, không cần nút riêng. */
  const handleMicClick = async () => {
    if (status === "recording") { finishRecording("manual"); return; }
    if (shadowQuestionDone) return;
    if (result) setResults((r) => { const n = { ...r }; delete n[idx]; return n; });
    setErrMsg("");
    setStatus("requesting");
    const mediaStarted = await startMediaRecording();
    if (!mediaStarted) return;
    if (!startRecording()) stopMediaRecording();
  };

  const goPrev = () => { if (idx > 0) setIdx(idx - 1); };
  const goNext = () => {
    if (!result || result.score < 80) return;
    if (idx < total - 1) { setIdx(idx + 1); return; }
    if (SHADOW_LINES.every((_, questionIndex) => results[questionIndex]?.score >= 80)) finishAndAssess(results);
  };

  const retryShadowing = () => {
    setShowCompletion(false);
    setIsRecheck(true);
    setFinalAssessment(null);
    setResults({});
    setHistory([]);
    setIdx(0);
    setStatus("idle");
  };

  if (showCompletion) {
    return (
      <SkillCompletionView
        title="Bạn đã hoàn thành Shadowing!"
        description="Tất cả câu đã đạt mức chính xác yêu cầu. Bạn có muốn luyện kiểm tra lại không?"
        assessment={finalAssessment}
        loading={assessingFinal}
        onBack={isRecheck ? onBack : (onFinish || onBack)}
        onRetry={retryShadowing}
      />
    );
  }

  return (
    <section className="sw-page">
      <div className="sw-topbar">
        <button className="fc2-back" onClick={onBack} aria-label="Về bài học"><ChevronLeft size={20} /></button>
        <span className="fc2-title"><Headphones size={18} color="#7C6FE4" /> Shadowing</span>
        <span className="sw-lesson-pill"><BookOpen size={13} /> Bài {String(lesson.no).padStart(2, "0")}</span>
        <div className="sw-top-progress">
          <span className="sw-progress-text">Câu {idx + 1} / {total}</span>
          <div className="fc2-progress-bar"><div style={{ width: `${((idx + 1) / total) * 100}%` }} /></div>
        </div>
        <span className="fc2-pill"><Flame size={13} color="#F0642E" fill="#F79A5E" /> {USER.streak}</span>
        <span className="fc2-pill gem"><Gem size={13} color="#7C6FE4" fill="#B9AFF0" /> {USER.gems.toLocaleString("vi-VN")}</span>
      </div>

      <div className="sw-body">
        {/* ===== CỘT CHÍNH ===== */}
        <div className="sw-main">
          <audio
            key={idx}
            ref={audioRef}
            src={line.audio}
            preload="metadata"
            onTimeUpdate={(e) => setAudioTime(e.target.currentTime)}
            onLoadedMetadata={(e) => setAudioDuration(e.target.duration)}
          />

          <div className="sw-card">
            <div className="sw-card-top">
              <button className={`sw-autoplay ${autoPlay ? "on" : ""}`} onClick={() => setAutoPlay((a) => !a)}>
                <Volume2 size={13} /> Tự động phát
              </button>
            </div>

            <div className="sw-sentence-row">
              <h2 className="sw-ko" lang="ko">{line.ko}</h2>
              <button className="sw-mini-play" onClick={playNative} aria-label="Nghe câu">
                <Volume2 size={16} color="#fff" />
              </button>
            </div>
            <p className="sw-vi">{line.vi}</p>

            <div className="sw-divider" />

            <div className="sw-controls">
              <button className="sw-side-ctrl" onClick={playNative}>
                <Volume2 size={20} color="#7C6FE4" />
                <span>Nghe câu</span>
              </button>
              <button
                className={`sw-mic-btn ${status === "recording" ? "rec" : ""} ${status === "requesting" ? "requesting" : ""}`}
                onClick={handleMicClick}
                disabled={status === "grading" || status === "requesting" || shadowQuestionDone}
                aria-label={status === "requesting" ? "Đang xin quyền micro" : status === "recording" ? "Dừng và chấm điểm" : shadowQuestionDone ? "Câu đã hoàn thành" : result ? "Ghi âm lại" : "Bắt đầu ghi âm"}
              >
                {status === "recording" ? (
                  <Square size={22} color="#fff" fill="#fff" />
                ) : shadowQuestionDone ? (
                  <CheckCircle2 size={25} color="#fff" />
                ) : result ? (
                  <RotateCcw size={24} color="#fff" />
                ) : (
                  <Mic size={26} color="#fff" />
                )}
              </button>
              <button className="sw-side-ctrl" onClick={playNative} aria-label="Nghe lại câu mẫu">
                <RotateCcw size={20} color="#7C6FE4" />
                <span>Nghe lại</span>
              </button>
            </div>
            <p className="sw-mic-caption">
              {status === "requesting"
                ? "Đang mở micro..."
                : status === "recording"
                ? "Đang ghi âm... bấm lại để dừng & chấm điểm"
                : status === "grading"
                ? "AI đang chấm điểm..."
                : shadowQuestionDone
                ? "Câu đã hoàn thành — hãy sang câu tiếp theo"
                : result
                ? "Bấm mic để ghi âm lại"
                : "Nhấn mic rồi nói theo câu trên"}
            </p>
            <p className={`sw-timer ${status === "recording" ? "is-recording" : ""} ${status === "recording" && recordingLimit - recordingElapsed <= 2 ? "is-ending" : ""}`}>
              {swFormatTime(recordingElapsed)} / {swFormatTime(recordingLimit)}
            </p>

            {status === "unsupported" && (
              <div className="sw-unsupported">
                <AlertTriangle size={16} color="#E8912E" />
                Trình duyệt này chưa hỗ trợ nhận diện giọng nói — cần dùng Chrome/Edge trên máy tính.
              </div>
            )}
            {status === "error" && (
              <div className="sw-unsupported err"><AlertTriangle size={16} color="#D64545" />{errMsg}</div>
            )}

            {result && status !== "grading" && (
              <div className="sw-result">
                <div className="sw-result-head"><Sparkles size={14} color="#7C6FE4" /> Kết quả mới nhất</div>
                <div className="sw-result-row">
                  <button className="sw-result-play" onClick={playNative} aria-label="Nghe lại câu mẫu">
                    <Play size={16} fill="#fff" color="#fff" />
                  </button>
                  <div className="sw-result-wave"><SwWaveBars /></div>
                  <span className="sw-result-time">{swFormatTime(audioDuration)}</span>
                  <div className="sw-accuracy">
                    <span>Độ khớp câu</span>
                    <b className={toneForScore(result.score)}>{result.score}%</b>
                  </div>
                </div>
                <div className="sw-ai-feedback">
                  <div className="sw-ai-meta">
                    <span className={`sw-ai-badge ${result.source === "worker-ai" ? "" : "fallback"}`}>
                      <Sparkles size={12} /> {result.source === "worker-ai" ? "AI chấm điểm" : "Chấm dự phòng"}
                    </span>
                    {result.source === "worker-ai" && result.model && <span className="sw-ai-model">{result.model}</span>}
                  </div>
                  <p><strong>AI nhận diện:</strong> <span lang="ko">{result.transcript}</span></p>
                  {result.strength && <p><strong>Điểm tốt:</strong> {result.strength}</p>}
                  {result.warning && <p className="sw-ai-warning">{result.warning}</p>}
                </div>
                <div className="sw-compare-row">
                  <button className="sw-compare-btn" onClick={playNative}>
                    <Volume2 size={14} /> Giọng mẫu
                  </button>
                  <button className="sw-compare-btn mine" onClick={playMyRecording} disabled={!recordedUrls[idx]}>
                    <Mic size={14} /> {recordedUrls[idx] ? "Giọng của tôi" : micBlocked ? "Không có quyền micro để ghi lại" : "Chưa có bản ghi"}
                  </button>
                </div>
                <div className="sw-word-chips">
                  {(result.words || []).map((w, i) => (
                    <span key={i} className={`sw-chip ${w.status}`}>
                      {w.word} {w.status === "ok" ? <CheckCircle2 size={12} /> : <XCircle size={12} />}
                    </span>
                  ))}
                </div>
                <div className={`sw-score-state ${toneForScore(result.score)}`}>
                  {result.score >= 80
                    ? <><CheckCircle2 size={15} /> Chính xác — bạn có thể sang câu tiếp theo.</>
                    : result.score >= 60
                      ? <><AlertTriangle size={15} /> Gần đúng — nghe lại và ghi âm thêm một lần nhé.</>
                      : <><XCircle size={15} /> Chưa đúng — đối chiếu các từ màu đỏ rồi thử lại.</>}
                </div>
                <p className="sw-tip"><Lightbulb size={14} color="#E8A93D" fill="#F7D98B" /> {result.tip}</p>
              </div>
            )}
          </div>
        </div>

        {/* ===== CỘT PHỤ ===== */}
        <div className="sw-side">
          <div className="sw-help-card">
            <div className="sw-help-title">Hỗ trợ học tập</div>
            <div className="sw-help-btns">
              <button className={helpPanel === "break" ? "on" : ""} onClick={() => setHelpPanel((p) => (p === "break" ? null : "break"))}>
                <span className="sw-help-ico"><Scissors size={18} color="#7C6FE4" /></span>
                Ngắt nhịp
              </button>
              <button className={helpPanel === "pron" ? "on" : ""} onClick={() => setHelpPanel((p) => (p === "pron" ? null : "pron"))}>
                <span className="sw-help-ico blue"><Smile size={18} color="#4A90E2" /></span>
                Phát âm thực tế
              </button>
              <button className={helpPanel === "tips" ? "on" : ""} onClick={() => setHelpPanel((p) => (p === "tips" ? null : "tips"))}>
                <span className="sw-help-ico gold"><Lightbulb size={18} color="#E8912E" /></span>
                Chú ý Shadowing
              </button>
            </div>
            {helpPanel === null && <p className="sw-help-hint">Chọn một mục ở trên để xem nội dung ↗</p>}
            {helpPanel === "break" && <p className="sw-help-content" lang="ko">{line.rhythmBreak}</p>}
            {helpPanel === "pron" && <p className="sw-help-content" lang="ko">{line.realPron}</p>}
            {helpPanel === "tips" && (
              <ul className="sw-tips-list">
                {line.tips.map((t, i) => (<li key={i}>{renderKo(t)}</li>))}
              </ul>
            )}
          </div>

          <div className="sw-history-card">
            <div className="sw-help-title"><Sparkles size={14} color="#7C6FE4" /> Lịch sử kết quả</div>
            {history.length === 0 ? (
              <div className="sw-history-empty">
                <SwBunnyEmpty />
                <p>Luyện tập vài câu để xem lịch sử kết quả tại đây nhé</p>
              </div>
            ) : (
              <div className="sw-history-list">
                {history.map((h, i) => (
                  <div key={i} className="sw-history-item">
                    <span className="sw-history-ko" lang="ko">{h.ko}</span>
                    <span className={`sw-history-score ${toneForScore(h.score)}`}>{h.score}%</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="fc-nav">
        <button className="fc-nav-btn" disabled={idx === 0} onClick={goPrev}><ChevronLeft size={18} /> Câu trước</button>
        <div className="fc-dots">
          {SHADOW_LINES.map((l, i) => (
            <button
              key={l.no}
              className={`fc-dot ${i === idx ? "on" : ""} ${results[i] ? (results[i].score >= 80 ? "rated-good" : results[i].score >= 60 ? "rated-vague" : "rated-forgot") : ""}`}
              onClick={() => setIdx(i)}
              aria-label={`Câu ${i + 1}`}
            />
          ))}
        </div>
        <button
          className="fc-nav-btn primary"
          disabled={!result || result.score < 80 || status === "grading" || status === "recording"}
          title={!result || result.score < 80 ? "Hãy ghi âm lại đến khi câu đạt từ 80 điểm" : undefined}
          onClick={goNext}
        >
          {idx === total - 1 ? "Hoàn thành" : "Câu tiếp"} <ChevronRight size={18} />
        </button>
      </div>
    </section>
  );
}

/* ------------------------------------------------------------------ */
/*  ÔN TẬP CUỐI BÀI — ngân hàng câu hỏi tạo từ chính dữ liệu thật của   */
/*  bài học (28 từ vựng + 2 ngữ pháp + 6 câu Shadowing). Mỗi lần vào    */
/*  ôn tập sẽ xáo trộn & chọn ngẫu nhiên 10 câu trong ngân hàng này,     */
/*  nên "mỗi lần một khác" dù nội dung gốc không đổi.                   */
/* ------------------------------------------------------------------ */
function pickDistractors(all, excludeIdx, n, getter) {
  const pool = all.map((_, i) => i).filter((i) => i !== excludeIdx);
  return shuffleArr(pool).slice(0, n).map((i) => getter(all[i]));
}

/* ------------------------------------------------------------------ */
/*  5 mức độ khó — số câu hỏi & dạng bài tăng dần theo số sao.          */
/*  (Số từ vựng "phạm vi" trong bản spec được xấp xỉ qua questionCount  */
/*  vì bài ôn lấy trực tiếp câu hỏi theo trọng số, không tách 2 bước    */
/*  "chọn từ rồi mới chọn câu hỏi" để tránh làm phức tạp không cần thiết) */
/* ------------------------------------------------------------------ */
/* Phân bổ 5 mức sao — đã giảm nhẹ cấp 1-4 để tránh quá tải (ban đầu 3★/4★  */
/* ra tới 37-42 câu, quá dài cho một lượt ôn). Giờ tăng dần đều đặn, dùng   */
/* grammarQuestions/dialogueCount làm SỐ LƯỢNG cụ thể thay vì lấy hết theo  */
/* pattern. Riêng 5★ vẫn là lựa chọn chủ đích "ôn đủ 100%" bài học.        */
const REVIEW_DIFFICULTY = [
  { stars: 1, label: "Rất dễ", vocabCount: 8, vocabTypes: ["image", "meaning"], listeningCount: 3, dialogueCount: 0, grammarQuestions: 0, writingCount: 0, shadowingCount: 0 },
  { stars: 2, label: "Dễ", vocabCount: 10, vocabTypes: ["image", "meaning", "fillblank", "translate"], listeningCount: 4, dialogueCount: 0, grammarQuestions: 2, writingCount: 0, shadowingCount: 0 },
  { stars: 3, label: "Trung bình", vocabCount: 12, vocabTypes: ["image", "meaning", "fillblank", "translate"], listeningCount: 4, dialogueCount: 2, grammarQuestions: 2, writingCount: 2, shadowingCount: 1 },
  { stars: 4, label: "Khó", vocabCount: 14, vocabTypes: ["meaning", "fillblank", "translate"], listeningCount: 5, dialogueCount: 3, grammarQuestions: 3, writingCount: 2, shadowingCount: 2 },
  { stars: 5, label: "Rất khó", vocabCount: VOCAB_SAMPLE.length, vocabTypes: ["meaning", "fillblank", "translate"], listeningCount: 6, dialogueCount: SHADOW_LINES.length - 1, grammarQuestions: 6, writingCount: 3, shadowingCount: 3 },
];

// Trộn mảng CÓ THỂ LẶP LẠI GIỐNG HỆT NHAU cho cùng 1 seed — dùng để sinh "đề
// thi chuẩn" giống nhau cho MỌI người dùng ở lần đầu chọn 1 mức sao (không
// dùng Math.random ở đây, khác với shuffleArr thường dùng cho "Đổi đề mới").
function seededShuffle(arr, seed) {
  let s = seed >>> 0 || 1;
  const rand = () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
  const out = [...arr];
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}
const standardExamTakenKey = (stars) => `standard-exam-taken:2-1:${stars}`;
async function hasTakenStandardExam(stars) {
  try { const r = await window.storage.get(standardExamTakenKey(stars)); return !!JSON.parse(r.value)?.taken; } catch (e) { return false; }
}
async function markStandardExamTaken(stars) {
  try { await window.storage.set(standardExamTakenKey(stars), JSON.stringify({ taken: true })); } catch (e) {}
}

/* --- lưu & đọc lịch sử ôn tập thật qua window.storage (persistent) --- */
const reviewHistoryKey = (lesson) => `review-history:2-1:${lesson.no}`;

async function loadReviewHistory(lesson) {
  try {
    const res = await window.storage.get(reviewHistoryKey(lesson));
    return res?.value ? JSON.parse(res.value) : {};
  } catch (e) { return {}; }
}
async function saveReviewHistory(lesson, history) {
  try { await window.storage.set(reviewHistoryKey(lesson), JSON.stringify(history)); } catch (e) {}
}

/* Lưu lại kết quả Shadowing phản xạ (từ Ôn tập) LÂU DÀI — trước đây kết quả
   này chỉ tồn tại trong phiên làm bài rồi mất, không có cách nào để tính
   chỉ số "Phản xạ" tổng hợp cho Tiến độ cá nhân. */
const REFLEX_HISTORY_KEY = "reflex-history:2-1";
async function saveReflexAttempts(reflexResults) {
  const valid = (reflexResults || []).filter((r) => !r.timedOut);
  if (valid.length === 0) return;
  let cur = { count: 0, timeLeftSum: 0, scoreSum: 0 };
  try { const r = await window.storage.get(REFLEX_HISTORY_KEY); cur = JSON.parse(r.value); } catch (e) {}
  valid.forEach((r) => { cur.count += 1; cur.timeLeftSum += r.timeLeftAtDone; cur.scoreSum += r.score; });
  try { await window.storage.set(REFLEX_HISTORY_KEY, JSON.stringify(cur)); } catch (e) {}
}
async function loadReflexStats() {
  try {
    const r = await window.storage.get(REFLEX_HISTORY_KEY);
    const cur = JSON.parse(r.value);
    if (!cur.count) return null;
    return { count: cur.count, avgTimeLeft: Math.round((cur.timeLeftSum / cur.count) * 10) / 10, avgScore: Math.round(cur.scoreSum / cur.count) };
  } catch (e) { return null; }
}

/* --- chọn câu hỏi theo trọng số: 70% sai nhiều, 20% chưa gặp, 10% đã thuộc --- */
function weightedPick(pool, n, history) {
  const buckets = { wrong: [], unseen: [], mastered: [] };
  pool.forEach((item) => {
    const h = history[item.key];
    if (!h) buckets.unseen.push(item);
    else if (h.wrong > 0 && h.wrong >= h.correct) buckets.wrong.push(item);
    else buckets.mastered.push(item);
  });
  const bySeenAsc = (a, b) => (history[a.key]?.lastSeenAt || 0) - (history[b.key]?.lastSeenAt || 0);
  buckets.wrong.sort(bySeenAsc);
  buckets.mastered.sort(bySeenAsc);
  buckets.unseen = shuffleArr(buckets.unseen);

  const targetWrong = Math.round(n * 0.7);
  const targetUnseen = Math.round(n * 0.2);
  const targetMastered = Math.max(0, n - targetWrong - targetUnseen);

  const picked = [];
  let shortfall = 0;
  [[buckets.wrong, targetWrong], [buckets.unseen, targetUnseen], [buckets.mastered, targetMastered]].forEach(([bucket, target]) => {
    const taken = bucket.splice(0, target);
    picked.push(...taken);
    shortfall += target - taken.length;
  });
  if (shortfall > 0) {
    const rest = shuffleArr([...buckets.wrong, ...buckets.unseen, ...buckets.mastered]);
    picked.push(...rest.slice(0, shortfall));
  }
  return shuffleArr(picked).slice(0, n);
}

/* --- chọn câu hỏi theo ĐÚNG phạm vi bao phủ của mức sao: từ vựng theo      */
/* trọng số (weightedPick), còn nghe hiểu/hội thoại/ngữ pháp lấy đủ theo    */
/* số lượng cấu hình — đảm bảo 5★ ôn đủ 100% nội dung bài, không random hết */
/* Có `seed`: dùng để sinh "ĐỀ THI CHUẨN" — cố định, GIỐNG NHAU cho mọi     */
/* người dùng ở cùng 1 mức sao, KHÔNG theo lịch sử cá nhân (để làm thang đo */
/* chung). Không có seed: hành vi cũ, chọn theo trọng số lịch sử cá nhân.   */
function buildCoverageSelection(difficulty, fullPool, history, seed) {
  let salt = 0;
  const shuffle = (arr) => (seed ? seededShuffle(arr, seed + (salt++) * 97) : shuffleArr(arr));
  const selected = [];

  let vocabWords;
  if (difficulty.vocabCount >= VOCAB_SAMPLE.length) {
    vocabWords = VOCAB_SAMPLE.map((w) => w.word);
  } else if (seed) {
    vocabWords = shuffle(VOCAB_SAMPLE).slice(0, difficulty.vocabCount).map((w) => w.word);
  } else {
    vocabWords = weightedPick(VOCAB_SAMPLE.map((w) => ({ key: `vocab:${w.word}`, word: w.word })), difficulty.vocabCount, history).map((x) => x.word);
  }
  vocabWords.forEach((word) => {
    const candidates = fullPool.filter((q) => q.key === `vocab:${word}` && difficulty.vocabTypes.includes(q.type));
    if (candidates.length) selected.push(shuffle(candidates)[0]);
  });

  const listeningQs = shuffle(fullPool.filter((q) => q.type === "listening")).slice(0, difficulty.listeningCount);
  selected.push(...listeningQs);

  const dialogueQs = shuffle(fullPool.filter((q) => q.type === "dialogue")).slice(0, difficulty.dialogueCount);
  selected.push(...dialogueQs);

  const grammarQs = shuffle(fullPool.filter((q) => q.type === "grammar")).slice(0, difficulty.grammarQuestions);
  selected.push(...grammarQs);

  return shuffle(selected);
}

// Chọn N câu Shadowing (phản xạ có đồng hồ đếm ngược) từ SHADOW_LINES thật.
function pickShadowingLines(count, seed) {
  const shuffle = seed ? (arr) => seededShuffle(arr, seed + 777) : shuffleArr;
  return shuffle(SHADOW_LINES).slice(0, count);
}

/* --- sinh đề "Ứng dụng" — người học tự viết câu, không chép nguyên văn --- */
function generateWritingPrompts(stars) {
  const words = shuffleArr(VOCAB_SAMPLE).map((w) => w.word);
  const gram = shuffleArr(GRAMMAR_SAMPLE);
  if (stars === 3) {
    return [
      { id: "w1", instruction: `Viết một câu sử dụng từ vựng: **${words[0]}**`, dialogue: false },
      { id: "w2", instruction: `Viết một câu sử dụng ngữ pháp: **${gram[0].pattern}**`, dialogue: false },
    ];
  }
  if (stars === 4) {
    return [
      { id: "w1", instruction: `Viết một câu có chứa ít nhất 2 từ vựng: **${words[0]}**, **${words[1]}**`, dialogue: false },
      { id: "w2", instruction: `Viết một câu sử dụng từ vựng **${words[2]}** và ngữ pháp **${gram[0].pattern}**`, dialogue: false },
    ];
  }
  return [
    { id: "w1", instruction: `Viết một câu có chứa ít nhất 3 từ vựng: **${words[0]}**, **${words[1]}**, **${words[2]}**`, dialogue: false },
    { id: "w2", instruction: `Viết một câu sử dụng từ vựng **${words[3]}** và ngữ pháp **${gram[0].pattern}**`, dialogue: false },
    { id: "w3", instruction: `Viết đoạn hội thoại ngắn (2 câu) sử dụng **${words[4]}**, **${words[5]}** và ngữ pháp **${gram[1]?.pattern || gram[0].pattern}**`, dialogue: true },
  ];
}

/* --- AI chấm bài viết thật — nhiều tiêu chí, có kiểm tra chép nguyên văn --- */
async function gradeWriting(prompt, userAnswer) {
  const plain = prompt.instruction.replace(/\*\*/g, "");
  const aiPrompt = `Bạn là giáo viên tiếng Hàn chấm bài viết ứng dụng của học viên người Việt.

Yêu cầu đề bài: ${plain}
Học viên đã viết: "${userAnswer}"

Chấm dựa trên: đúng ngữ pháp, đúng cách dùng từ vựng, đúng ngữ cảnh, độ tự nhiên, chính tả, trợ từ, mức độ giống người bản xứ. Nếu câu gần giống nguyên văn ví dụ có sẵn trong sách thay vì tự sáng tạo, hãy trừ điểm và ghi rõ trong phần lỗi.

Trả lời CHỈ bằng JSON, không markdown, không chữ nào khác:
{
  "score": <số nguyên 0-100>,
  "strengths": "<1 câu tiếng Việt, khen cụ thể>",
  "errors": "<1-2 câu tiếng Việt, chỉ lỗi cụ thể nếu có, hoặc 'Không có lỗi đáng kể' nếu tốt>",
  "naturalVersion": "<câu tiếng Hàn tự nhiên hơn nếu cần chỉnh, hoặc giữ nguyên nếu đã tốt>",
  "explanation": "<1 câu tiếng Việt giải thích ngắn gọn>"
}`;
  try {
    const { value: parsed } = await requestAIJson(aiPrompt);
    if (typeof parsed.score !== "number") throw new Error("malformed");
    return parsed;
  } catch (e) {
    return { score: 60, strengths: "Bạn đã thử viết câu bằng tiếng Hàn.", errors: "Không thể chấm chi tiết lúc này do lỗi kết nối.", naturalVersion: userAnswer, explanation: "" };
  }
}


async function generateReviewFeedback(wrongLabels) {
  if (!wrongLabels.length) return "Bạn làm rất tốt, không có lỗi nào đáng chú ý trong lượt ôn tập này! 🎉";
  // Nhận xét tổng kết đơn giản không cần AI; tránh gọi dịch vụ ngoài không cần thiết.
  return `Bạn cần ôn lại thêm: ${wrongLabels.slice(0, 3).join(", ")}. Làm lại các câu này một lượt để ghi nhớ chắc hơn nhé.`;
}

